import {accompaniedCompletion,prepareOfficeReview} from './accompanied.js';
import {createAssessmentPDF,readAssessmentPDF} from './assessment-pdf.js';
import {externalTestView,bindExternalTest} from './external-test.js';
import {officeReviewView,bindOfficeReview} from './office-evaluation-view.js';
import {createOffice,applyOffice} from './office.js';
import {officeView,bindOffice} from './office-view.js';
import {reloadView,manageView} from './view-state.js';
import {discoveryQuestions,blankRecord,integratedResults,integratedRadar} from './integrated.js';
import {interviewView,reserveView,profileView,reportView,evidenceView} from './integrated-view.js';
import {createAssessment,QUALIFIERS,discoveryResults,coefficient,results,median,validateImport,escapeHTML as esc} from './core.js';
import {autoSuggestion,validatePractical} from './practical.js';
import {discoveryRadar,discoveryProfile,discoveryReport,practicalEvidence} from './discovery-view.js';
const [content,material]=await Promise.all([fetch('data/content.json').then(r=>r.json()),fetch('data/games.json').then(r=>r.json())]);
const qs=discoveryQuestions(content);
const externalMode=new URLSearchParams(location.search).has('teste');
const {games,matrix}=material, STORAGE=externalMode?'lado-a-teste-externo-v1':'lado-a-evaluations-v1';
const demoAnswers=await fetch('data/demo.json').then(r=>r.json());
let assessments=[],storageAvailable=true,recoveryFailed=false;
try{const parsed=JSON.parse(localStorage.getItem(STORAGE)||'[]');if(!Array.isArray(parsed))throw Error();assessments=parsed.map(value=>validatePractical(validateImport(value,material.docs),games,matrix));}catch{storageAvailable=false;recoveryFailed=true;}
let a=assessments[0]||createAssessment();if(!assessments.length)assessments.push(a);
let page=0,interviewIndex=a.discovery.lastQuestion,probeIndex=0,gameIndex=0,stageIndex=0,participant=false,selectedAxis=null,selectedDiscoveryBlock=null,discoveryPre=!a.discovery.preRegistrationComplete,visible=[true,true,true],saveMessage='';
let officeOpen=false,officeReviewOpen=false;
let profileTab='summary';
const root=document.querySelector('#app');
const initialView=reloadView();
if(initialView){const v=initialView.view,found=assessments.find(item=>item.id===v.assessmentId);if(found&&[0,1,3,4].includes(v.page)){a=found;page=v.page;officeOpen=!!v.office&&!!a.office;officeReviewOpen=!!v.officeReview&&a.office?.status==='completed';discoveryPre=!!v.pre;profileTab=['summary','evidence','edit'].includes(v.tab)?v.tab:'summary';const index=qs.findIndex(q=>q.id===v.questionId);if(index>=0)a.integrated.lastQuestion=index;}}
const viewState=manageView(root,()=>({assessmentId:a.id,page,pre:discoveryPre,questionId:qs[a.integrated.lastQuestion].id,tab:profileTab,office:officeOpen,officeReview:officeReviewOpen,externalPhase:externalMode?a.external?.phase:null,externalQuestion:externalMode?a.external?.questionIndex:null,officeStage:officeOpen||externalMode&&a.external?.phase==='office'?a.office?.currentStage:null}),initialView);
function render(){viewState.before();renderContent();viewState.after();}
root.addEventListener('keydown',e=>{if(!e.target.matches('[role="tab"]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=['summary','evidence','edit'],i=tabs.indexOf(profileTab);profileTab=e.key==='Home'?tabs[0]:e.key==='End'?tabs[2]:tabs[(i+(e.key==='ArrowRight'?1:2))%3];render();requestAnimationFrame(()=>document.querySelector('#tab-'+profileTab)?.focus({preventScroll:true}));});

const reviewDefault=()=>({status:'pendente',correct:false,independent:true,help:'',access:'',answer:'',notes:'',familiarity:''});
const field=(label,key,value,type='text',attrs='')=>`<label class="field">${label}<${type==='textarea'?'textarea':'input'} ${type==='textarea'?'':`type="${type}"`} data-field="${key}" ${attrs} ${type==='textarea'?'':`value="${esc(value)}"`}>${type==='textarea'?esc(value)+'</textarea>':''}</label>`;
const select=(label,key,value,options)=>`<label class="field">${label}<select data-field="${key}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;
function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.style.display='none',4500);}
function save(){a.integrated.currentQuestionId=qs[a.integrated.lastQuestion].id;a.updatedAt=new Date().toISOString();for(const record of [...Object.values(a.verbal),...Object.values(a.practical).map(p=>p.review).filter(Boolean)])if(record.status==='observado'&&!record.independent&&!record.help.trim())record.status='pendente';try{if(recoveryFailed)throw Error('Recuperação pendente');localStorage.setItem(STORAGE,JSON.stringify(assessments));storageAvailable=true;saveMessage='Salvo neste navegador · '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});}catch{storageAvailable=false;saveMessage='Falha ao salvar. Exporte JSON para preservar o progresso.';}const el=document.querySelector('#save-status');if(el){el.textContent=saveMessage;el.className=storageAvailable?'status':'status error';}}
function completion(){return [a.identity.code.trim()?1:0,qs.filter(q=>a.integrated.records[q.id]?.answer.trim()).length/qs.length,a.status==='revisado'?1:0];}
function renderContent(){if(externalMode){root.innerHTML=externalTestView(a,qs,material.docs,saveMessage);return;}if(officeReviewOpen){document.body.classList.remove('participant');root.innerHTML=`<main class="office-review-container"><p id="save-status" class="status">${esc(saveMessage)}</p>${officeReviewView(a,material.docs)}</main>`;return;}if(officeOpen&&a.office){document.body.classList.remove('participant');root.innerHTML=officeView(a,material.docs,saveMessage);return;}document.body.classList.toggle('participant',participant);const pct=Math.round(completion().reduce((x,y)=>x+y,0)/3*100);root.innerHTML=`<div class="shell">${participant?'':`<aside class="sidebar"><div class="brand"><img src="assets/lado-a-logo.svg" alt="LADO A"><small>EMPLOYABILITY</small></div><p>Avaliação e Perfil Profissional Individualizado</p><nav>${['Cadastro','Entrevista Discovery','Simulações profissionais','Perfil profissional'].map((n,j)=>{const i=[0,1,3,4][j];return `<button data-action="page" data-value="${i}" class="${page===i?'active':''}">${j+1}. ${n}</button>`;}).join('')}</nav><div><span class="muted" style="color:#bdd5be">${pct}% do percurso registrado</span><div class="progress"><span style="width:${pct}%"></span></div></div><footer>Descobrindo habilidades,<br>construindo possibilidades.<br><br>Discovery 0.4<br>Uso com dados fictícios</footer></aside>`}<main class="content"><header class="topbar"><div><div class="eyebrow">${participant?'LADO A · Simulação de trabalho':'LADO A · Ambiente do avaliador'}</div><h1>${participant?'Uma atividade de cada vez':esc(a.identity.code||'Nova avaliação')}</h1><span id="save-status" class="status">${esc(saveMessage||'Salvamento local automático')}</span></div><div class="actions"></div></header>${participant?'':toolbar()}${[registration,integratedInterview,integratedInterview,pendingGames,profile][page]()}</main></div><article id="print-report" class="print-only"></article>`;}
function toolbar(){return `<div class="toolbar"><select id="assessment-select" aria-label="Avaliação">${assessments.map(x=>`<option value="${esc(x.id)}" ${x.id===a.id?'selected':''}>${esc(x.identity.code||'Sem código')} · ${esc(x.identity.date)}</option>`).join('')}</select><button data-action="new">＋ Nova avaliação</button><details class="more-actions"><summary>Mais ações</summary><div class="menu-panel"><button data-action="export">Exportar dados (JSON)</button><button data-action="import">Importar avaliação</button><button data-action="demo">Demonstração fictícia</button></div></details><input type="file" id="import-file" accept="application/json,application/pdf,.json,.pdf" hidden></div>`;}

function registration(){return `<h2>Conhecer a pessoa, ampliar possibilidades.</h2><p class="lead">Registre as escolhas, o contexto e os recursos de comunicação antes de iniciar.</p><div class="warning">Piloto local: utilize participantes fictícios. Os registros ficam neste navegador, sem autenticação ou proteção de acesso. O modo participante apenas oculta informações na interface. Exporte JSON para manter uma cópia; limpar os dados do navegador pode apagar avaliações.</div><div class="card"><h3>Identificação da avaliação</h3><div class="grid">${field('Código fictício do participante','identity.code',a.identity.code)}${field('Idade','identity.age',a.identity.age,'number','min="0" max="120"')}${field('Data da avaliação','identity.date',a.identity.date,'date')}${field('Profissional responsável','identity.professional',a.identity.professional)}${field('Modalidade de comunicação preferida','identity.communication',a.identity.communication)}${field('Observações iniciais e condições de acesso','identity.notes',a.identity.notes,'textarea')}</div><label class="check"><input type="checkbox" data-field="identity.agreement" ${a.identity.agreement?'checked':''}>Finalidade, possibilidade de pausa e formas de participação foram esclarecidas e houve concordância para a avaliação.</label><button class="primary" data-action="start-interview">Iniciar entrevista →</button></div><div class="grid three">${[['01','Escutar','Interesses e experiências, nas palavras do participante.'],['02','Observar','Sondagens e ações em contextos profissionais simulados.'],['03','Construir','Um perfil contextualizado, revisado pelo profissional.']].map(([n,title,desc])=>`<div class="card"><span class="eyebrow">${n}</span><h3 style="margin-top:15px">${title}</h3><p class="muted">${desc}</p></div>`).join('')}</div>`;}
function discovery(){
  if(discoveryPre)return `<h2>Pré-cadastro da entrevista</h2><p class="lead">Registre as informações iniciais antes das 36 perguntas Discovery. Você poderá revisar estes campos durante a entrevista e no perfil profissional.</p><div class="card"><span class="badge">Discovery · informações iniciais</span><h3 style="margin-top:20px">Interesses, experiências e preferências</h3><p class="muted">Preencha com as informações disponíveis, preservando as palavras e escolhas do participante. O preenchimento não bloqueia o início das perguntas.</p>${reportFields(['interests','experience','preferences'])}<button class="primary" data-action="discovery-continue">Continuar para as perguntas →</button></div>`;
  const q=content.interview[interviewIndex],r=a.interview[q.id]||{answer:'',notes:'',qualifier:null,evidenceIds:[]};
  const available=matrix.filter(op=>a.practical[op.stage]?.first||['observado','NO'].includes(a.practical[op.id]?.review?.status));
  return `<h2>Entrevista Discovery</h2><p class="lead">36 perguntas originais. Qualificadores registrados pelo avaliador alimentam o radar Discovery; o conteúdo das respostas é preservado.</p><div class="actions" style="margin-bottom:20px"><button data-action="discovery-pre">Editar pré-cadastro</button></div><div class="card"><div class="section-title"><span class="badge">${esc(content.blocks[q.block])}</span><span class="muted">${interviewIndex+1} de 36</span></div><div class="progress"><span style="width:${(interviewIndex+1)/36*100}%"></span></div><p class="question">${esc(q.text)}</p>${field('Resposta do participante',`interview.${q.id}.answer`,r.answer,'textarea')}
  <fieldset class="qualifiers"><legend>Habilidade demonstrada na evidência registrada</legend><p class="muted" id="qualifier-help">Nesta escala, “Não se aplica” significa habilidade não demonstrada na evidência registrada e vale 0. Perguntas não avaliadas ficam sem pontuação. Preferências diferentes das esperadas não justificam nota zero.</p><div class="qualifier-options">${Object.entries(QUALIFIERS).map(([key,option])=>`<label class="qualifier-option"><input type="radio" name="qualifier-${q.id}" data-field="interview.${q.id}.qualifier" value="${key}" aria-describedby="qualifier-help" ${r.qualifier===key?'checked':''}><span>${option.label}<small>${option.points} pontos</small></span></label>`).join('')}</div><button class="clear-qualifier" data-action="discovery-clear">Deixar como não avaliada</button></fieldset>
  ${r.notes?`<details class="legacy-notes"><summary>Observações anteriores</summary><p class="report-section">${esc(r.notes)}</p></details>`:''}
  <details class="discovery-evidence-picker"><summary>Vincular evidências práticas (opcional)</summary><p class="muted">Selecione oportunidades já registradas para consultar as ações e a revisão profissional. Os vínculos não alteram automaticamente o qualificador.</p>${available.length?available.map(op=>`<div class="evidence-choice"><label class="check"><input type="checkbox" data-evidence-question="${q.id}" value="${esc(op.id)}" ${r.evidenceIds.includes(op.id)?'checked':''}><span><strong>${esc(op.id)} · ${esc(games.find(g=>g.id===op.game).name)}</strong><small>${esc(op.target)}</small></span></label><button data-action="discovery-evidence" data-value="${esc(op.id)}">Consultar</button></div>`).join(''):'<p>Nenhuma oportunidade prática registrada. Você pode retornar após realizar as simulações.</p>'}</details>
  <div class="questionnav"><button data-action="discovery-prev" ${interviewIndex===0?'disabled':''}>← Anterior</button><select id="discovery-jump" aria-label="Selecionar pergunta" style="max-width:180px">${content.interview.map((q,i)=>`<option value="${i}" ${i===interviewIndex?'selected':''}>Pergunta ${i+1}</option>`).join('')}</select><button class="primary" data-action="discovery-next">${interviewIndex===35?'Ir para sondagens':'Próxima →'}</button></div></div>`;
}
function reviewFields(prefix,r){return `<div class="grid">${select('Situação do registro',`${prefix}.status`,r.status,[['pendente','Aguardando revisão'],['observado','Observado e revisado'],['NO','Não observado / recusado / interrompido']])}${select('Resposta conforme o critério?',`${prefix}.correct`,String(r.correct),[['false','Não'],['true','Sim']])}${select('Independência',`${prefix}.independent`,String(r.independent),[['true','Independente'],['false','Com ajuda que orienta a resposta']])}${field('Ajuda fornecida (obrigatória quando não independente)',`${prefix}.help`,r.help)}${field('Familiaridade, exposição anterior ou ensino prévio',`${prefix}.familiarity`,r.familiarity||'')}${field('Acessibilidade e condições de aplicação',`${prefix}.access`,r.access)}${field('Observações / motivo de não observação',`${prefix}.notes`,r.notes,'textarea')}</div>`;}
function verbal(){const p=content.probes[probeIndex];const r=a.verbal[p.id]||reviewDefault();return `<h2>Sondagens relacionais RFT</h2><p class="lead">Registre a primeira resposta antes de consultar o critério. Aceite fala, escrita, apontar ou comunicação alternativa.</p><div class="card"><div class="section-title"><span class="badge">${esc(content.axes[p.axis])} · ${p.id}</span><span class="muted">${probeIndex+1} de 30</span></div><div class="progress"><span style="width:${(probeIndex+1)/30*100}%"></span></div><p class="question">${esc(p.prompt)}</p>${field('Primeira resposta literal ou ação observada',`verbal.${p.id}.answer`,r.first?.answer??r.answer,'textarea',r.first?'readonly':'')}${r.first?'<p class="muted">Primeira resposta preservada após a revisão; correções podem ser registradas nas observações.</p>':''}<details><summary>Critério original — exclusivo do avaliador</summary><div class="instructions">${esc(p.criterion)}</div></details>${reviewFields(`verbal.${p.id}`,r)}<p class="muted">Sem feedback corretivo na sondagem inicial. Recursos de acesso não retiram automaticamente a independência. Registre familiaridade e histórico de ensino nas observações.</p><div class="questionnav"><button data-action="probe-prev" ${probeIndex===0?'disabled':''}>← Anterior</button><select id="probe-jump" aria-label="Selecionar sondagem" style="max-width:180px">${content.probes.map((p,i)=>`<option value="${i}" ${i===probeIndex?'selected':''}>${p.id} · ${esc(content.axes[p.axis])}</option>`).join('')}</select><button class="primary" data-action="probe-next">${probeIndex===29?'Ir para simulações':'Próxima →'}</button></div></div>`;}
function currentStage(){return games[gameIndex].stages[stageIndex];}
function initDraft(s){const draft={};if(s.type==='order')for(const g of s.groups)draft[g.name]=[...g.ids];if(s.type==='stock')for(const item of s.order)draft[item.id]={quantity:'',product:'',decision:'',reason:''};return draft;}
function stageRecord(s){return a.practical[s.id] ||= {draft:initDraft(s),actions:[],conditions:{help:'',access:'',notes:''}};}
function practical(){const game=games[gameIndex],s=currentStage(),r=stageRecord(s);return `<h2>${participant?esc(game.name):'Simulações profissionais'}</h2><p class="lead">${participant?'Você pode usar seu modo de comunicação preferido, pedir esclarecimentos ou uma pausa.': 'A primeira entrega é preservada. A correção objetiva não classifica automaticamente a independência ou o repertório relacional.'}</p><div class="tabs">${games.map((g,i)=>`<button class="${i===gameIndex?'active':''}" data-action="game" data-value="${i}">${esc(g.name)}</button>`).join('')}</div>${participant?'':`<p class="muted">${esc(game.origin)} · Mapeamentos relacionais: proposta digital para revisão.</p>`}<div class="card"><div class="section-title"><h3>${stageIndex+1}. ${esc(s.title)}</h3><span class="badge">Etapa ${stageIndex+1} / ${game.stages.length}</span></div>${['office','stock'].includes(game.id)?'<p class="muted">Data do cenário: <strong>15/06/2027</strong> (simulação fixa).</p>':''}<div class="instructions">${esc(s.instruction)}</div>${s.type==='stock'?'<div class="instructions">Regras O-17: código idêntico; quantidade exata; sem substituição não autorizada; não separar avariados nem itens com validade anterior a 15/06/2027. Se o estoque for insuficiente, registre a divergência e peça orientação.</div>':''}${r.first?`<div class="readonly">Primeira entrega registrada. ${participant?'Você pode seguir para a próxima etapa.':'Os dados originais estão preservados para revisão.'}</div>`:board(s,r)}${participant?'':`<details ${r.first?'':'open'}><summary>Condições da primeira execução</summary>${r.first?`<p class="muted">Condições registradas na entrega: ${esc(JSON.stringify(r.first.conditions))}</p>`:`<div class="grid">${field('Ajuda que orientou a resposta',`practical.${s.id}.conditions.help`,r.conditions.help)}${field('Recursos de acessibilidade',`practical.${s.id}.conditions.access`,r.conditions.access)}${field('Observações da aplicação',`practical.${s.id}.conditions.notes`,r.conditions.notes,'textarea')}</div>`}</details>`}<div class="questionnav"><button data-action="stage-prev" ${stageIndex===0?'disabled':''}>← Etapa anterior</button>${r.first?'<button class="primary" data-action="stage-next">Próxima etapa →</button>':'<button class="primary" data-action="submit-stage">Registrar primeira entrega</button>'}</div></div>${participant?'':reviewStage(s,r)}`;}
function objectText(item){return `${item.sector?`Setor: ${esc(item.sector)} · Prazo: ${esc(item.date)} · ${esc(item.status)}`:item.stock!==undefined?`Estoque: ${item.stock} · ${esc(item.state)} · Validade: ${esc(item.expiry)}`:item.workshop?`Oficina: ${esc(item.workshop)} · Chegada: ${esc(item.time)}`:''}`;}
function draftSelect(id,value,options,label='Destino'){return `<label>${esc(label)}<select data-draft="${esc(id)}"><option value="">Selecionar…</option>${options.map(o=>`<option ${value===o?'selected':''} value="${esc(o)}">${esc(o)}</option>`).join('')}</select></label>`;}
function board(s,r){const d=r.draft;if(s.type==='classify')return `<div class="taskboard">${s.items.map(item=>`<div class="object" draggable="true" data-object="${item.id}"><strong>${item.id} · ${esc(item.name)}</strong><small>${objectText(item)}</small>${draftSelect(item.id,d[item.id],s.options)}</div>`).join('')}</div><p class="muted">Selecione o destino de cada cartão${participant?'':', ou arraste para um recipiente'}.</p><div class="tabs">${s.options.map(o=>`<div class="object" data-drop="${esc(o)}" tabindex="0">${esc(o)}</div>`).join('')}</div>${s.message?`<label class="field">Mensagem ao responsável / estratégia utilizada<textarea data-draft="message">${esc(d.message)}</textarea></label>`:''}`;
if(s.type==='order')return `<div class="grid">${s.groups.map(g=>`<div class="object"><h3>${esc(g.name)}</h3>${d[g.name].map((id,i)=>{const item=s.items.find(x=>x.id===id);return `<div class="ordered"><span class="item"><strong>${id} · ${esc(item.name)}</strong><small>${objectText(item)}</small></span><button aria-label="Mover ${id} para cima" data-action="move" data-group="${esc(g.name)}" data-value="${i}" data-direction="-1" ${i===0?'disabled':''}>↑</button><button aria-label="Mover ${id} para baixo" data-action="move" data-group="${esc(g.name)}" data-value="${i}" data-direction="1" ${i===d[g.name].length-1?'disabled':''}>↓</button></div>`;}).join('')}</div>`).join('')}</div>`;
if(s.type==='mark'||s.type==='checklist')return `<div class="taskboard">${s.items.map(item=>`<div class="object"><strong>${item.id} · ${esc(item.name)}</strong><small>${objectText(item)}</small><label class="check"><input type="checkbox" data-draft="${item.id}" ${d[item.id]?'checked':''}>${s.type==='mark'?'Urgente':'Conferido'}</label></div>`).join('')}</div>${s.type==='checklist'?`<label class="field">Descreva ou registre a estratégia demonstrada<textarea data-draft="message">${esc(d.message)}</textarea></label>`:''}`;
if(s.type==='stock')return `<details open><summary>Estoque disponível</summary><div class="taskboard">${s.items.map(p=>`<div class="object"><strong>${p.id} · ${esc(p.name)}</strong><small>${objectText(p)}</small></div>`).join('')}</div></details><h3>Linhas do pedido O-17</h3>${s.order.map(item=>`<div class="object" style="margin-bottom:12px"><strong>${item.id} · Solicitado: ${item.quantity}</strong><div class="grid">${draftSelect(item.id+'.product',d[item.id].product,s.items.map(p=>p.id),'Código selecionado')}<label>Quantidade separada<input type="number" min="0" max="99" data-draft="${item.id}.quantity" value="${esc(d[item.id].quantity)}"></label>${draftSelect(item.id+'.decision',d[item.id].decision,['SEPARAR','IMPEDIMENTO'],'Decisão')}${draftSelect(item.id+'.reason',d[item.id].reason,['Sem impedimento','Quantidade insuficiente','Avariado','Vencido','Outro / pedir orientação'],'Motivo')}</div></div>`).join('')}<label class="field">Status do pedido / mensagem ao responsável<textarea data-draft="message">${esc(d.message)}</textarea></label>`;
if(s.type==='chat')return `<div class="object"><span class="badge">Mensagem do supervisor / colega</span><p>${esc(s.instruction)}</p></div>${s.clarification?`<label class="field">Pergunta ou hipótese a verificar<textarea data-draft="question">${esc(d.question)}</textarea></label><button data-action="clarify">Enviar pedido de esclarecimento</button>${d.clarified?`<div class="instructions">${esc(s.clarification)}</div>`:''}`:''}<label class="field">Sua mensagem / resposta<textarea data-draft="answer">${esc(d.answer)}</textarea></label><p class="muted">Se a resposta ocorrer por fala ou comunicação alternativa, o profissional pode registrá-la neste campo.</p>`;
if(s.type==='interview')return s.questions.map((q,i)=>`<label class="field">${esc(q)}<textarea data-draft="Q${i}">${esc(d['Q'+i])}</textarea></label>`).join('');
if(s.type==='route'||s.type==='position')return `<div class="grid">${s.rows.map(row=>`<div class="object"><p>${esc(row.label)}</p>${s.type==='position'?`<div class="tabs">${s.options.map(option=>`<button data-action="position" data-row="${row.id}" data-value="${option}" class="${d[row.id]===option?'active':''}">${d[row.id]===option?'● ':''}${option}</button>`).join('')}</div>`:draftSelect(row.id,d[row.id],row.options,'Encaminhar / atualizar')}</div>`).join('')}</div>`;
return '';}
function reviewStage(s,r){const ops=matrix.filter(m=>m.stage===s.id);return `<div class="card"><h3>Revisão profissional da etapa</h3>${r.first?`<details><summary>Primeira tentativa e ações registradas</summary><pre class="records">${esc(JSON.stringify(r.first,null,2))}</pre></details>`:'<p class="muted">Registre a primeira entrega antes de revisar as oportunidades. Use NO se não houve observação.</p>'}${!ops.length?`<p class="muted">Etapa mantida como evidência complementar, sem pontuação relacional própria.</p>`:''}${ops.map(op=>{const review=a.practical[op.id]?.review||reviewDefault();return `<details><summary>${esc(op.id)} · ${op.axis===null?'Qualitativo':esc(content.axes[op.axis])} · ${review.status==='pendente'?'pendente':esc(review.status)}</summary><p>${esc(op.target)}</p><p class="muted">Critério: ${esc(op.expected)}</p><p class="muted">${op.source==='novo'?'Item novo proposto':'Adaptação de atividade original'} · correspondência relacional proposta, requer revisão.</p>${r.first&&autoSuggestion(op,s,r.first.draft)!==null?`<p class="badge">Verificação objetiva: ${autoSuggestion(op,s,r.first.draft)?'conforme critério':'divergência registrada'} — confirme a aplicação.</p>`:''}${field('Resposta / ação observada',`practical.${op.id}.review.answer`,review.answer,'textarea')}${reviewFields(`practical.${op.id}.review`,review)}</details>`;}).join('')}</div>`;}
const reportLabels={interests:'Interesses profissionais e funções que deseja explorar',experience:'Experiências anteriores e habilidades relatadas',preferences:'Preferências de trabalho e escolhas do participante',observed:'Habilidades relatadas — exemplos e contexto',facilitators:'Condições facilitadoras e recursos de apoio',develop:'Repertórios a desenvolver em situações específicas',possibilities:'Possibilidades profissionais — hipóteses para exploração',considerations:'Considerações do profissional e limites das evidências',participantReview:'Correções, escolhas e revisão pelo participante'};
function reportFields(keys=Object.keys(reportLabels)){return keys.map(key=>field(reportLabels[key],`report.${key}`,a.report[key]||'','textarea')).join('');}
function resultTable(rows){return `<div class="tablewrap"><table><thead><tr><th>Eixo</th><th>Verbal · válidas</th><th>Prático · válidas</th><th>Média descritiva</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button data-action="axis" data-value="${r.axis}">${esc(r.name)}</button></td><td>${r.verbal.value===null?'Dados insuficientes':r.verbal.value+'%'} · ${r.verbal.count}/3</td><td>${r.practical.value===null?'Dados insuficientes':r.practical.value+'%'} · ${r.practical.count}/${matrix.filter(m=>m.axis===r.axis).length}</td><td>${r.integrated===null?'—':r.integrated+'%'}</td></tr>`).join('')}</tbody></table></div>`;}
function radar(rows,forPrint=false){const cx=285,cy=255,R=170;const pos=(i,value)=>{const angle=2*Math.PI*i/10-Math.PI/2;return [cx+Math.cos(angle)*R*value/100,cy+Math.sin(angle)*R*value/100];};const points=values=>values.map((v,i)=>pos(i,v).join(',')).join(' ');let svg=`<svg class="radar" viewBox="0 0 570 520" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Radar comparativo. Dados ausentes não são convertidos em zero."><rect width="570" height="520" fill="white"/>`;
for(const tick of [25,50,75,100])svg+=`<polygon points="${points(Array(10).fill(tick))}" fill="none" stroke="#dce5da"/><text x="290" y="${cy-R*tick/100-5}" font-size="10" fill="#687b6b">${tick}</text>`;
rows.forEach((r,i)=>{const end=pos(i,100),label=pos(i,125);svg+=`<line x1="${cx}" y1="${cy}" x2="${end[0]}" y2="${end[1]}" stroke="#e2e8df"/><text x="${label[0]}" y="${label[1]}" text-anchor="middle" dominant-baseline="middle" font-family="Arial,sans-serif" font-size="12" fill="#334c3a" ${forPrint?'':`data-action="axis" data-value="${i}" tabindex="0" role="button" style="cursor:pointer"`}>${esc(r.name)}</text>`;});
const series=[rows.map(r=>r.verbal.value),rows.map(r=>r.practical.value),rows.map(r=>r.integrated)],colors=['#2f6ccc','#2a8650','#a67d15'];series.forEach((values,k)=>{if(!visible[k])return;if(values.every(v=>v!==null))svg+=`<polygon points="${points(values)}" fill="${colors[k]}" fill-opacity=".07" stroke="${colors[k]}" stroke-width="2.5"/>`;else values.forEach((v,i)=>{const next=(i+1)%10;if(v!==null&&values[next]!==null){const p=pos(i,v),q=pos(next,values[next]);svg+=`<line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" stroke="${colors[k]}" stroke-width="2.5"/>`;}});values.forEach((v,i)=>{if(v===null)return;const p=pos(i,v);svg+=`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="${colors[k]}" ${forPrint?'':`data-action="axis" data-value="${i}" tabindex="0" role="button" style="cursor:pointer"`}><title>${esc(rows[i].name)}: ${v}%</title></circle>`;});});svg+=`<text x="285" y="493" text-anchor="middle" font-family="Arial,sans-serif" font-size="11" fill="#526a58">Azul: verbal · Verde: prático · Dourado: média descritiva</text></svg>`;return svg;}
function axisDetails(axis){const verbalItems=content.probes.filter(p=>p.axis===axis),ops=matrix.filter(p=>p.axis===axis);return `<div class="card"><h3>Evidências · ${esc(content.axes[axis])}</h3><h4>Sondagens verbais</h4>${verbalItems.map(p=>{const r=a.verbal[p.id];return `<details><summary>${p.id} · ${esc(r?.status||'pendente')}</summary><p>${esc(p.prompt)}</p><p>Resposta: ${esc(r?.answer||'Sem registro')}</p><p class="muted">Independência: ${r?.status==='observado'?(r.independent?'sim':'com ajuda'):'—'} · Ajuda: ${esc(r?.help||'Não registrada')} · Condições: ${esc(r?.access||'Não registradas')}</p><p>${esc(r?.notes||'')}</p></details>`;}).join('')}<h4>Oportunidades práticas propostas</h4>${ops.map(p=>{const r=a.practical[p.id]?.review;return `<details><summary>${esc(p.id)} · ${esc(games.find(g=>g.id===p.game).name)} · ${esc(r?.status||'pendente')}</summary><p>${esc(p.target)}</p><p class="muted">Sondagens relacionadas: ${p.verbal.join(', ')}. ${p.source==='novo'?'Item digital novo.':'Atividade adaptada do manual.'}</p><p>Critério: ${esc(p.expected)}</p><p>Resposta: ${esc(r?.answer||'Consultar primeira entrega da etapa')}</p><p class="muted">Ajuda: ${esc(r?.help||'Não registrada')} · Acesso: ${esc(r?.access||'Não registrado')}</p><p>${esc(r?.notes||'')}</p></details>`;}).join('')}</div>`;}
function legacyProfile(){const rows=results(a,content,matrix),summary=median(rows.map(r=>r.integrated));return `<h2>Perfil Profissional Individualizado</h2><p class="lead">Interesses, evidências e condições de desempenho para construir possibilidades com o participante.</p>${discoveryProfile(a,content,games,matrix,selectedDiscoveryBlock)}<div class="warning">Instrumento piloto autoral. Os percentuais descrevem respostas corretas e independentes na primeira tentativa; não são escores psicométricos, diagnóstico ou critérios de contratação. Mínimo operacional: duas oportunidades válidas por eixo e modalidade. A média pode ocultar diferenças entre modalidades.</div><div class="card"><h3>Revisão da matriz prática</h3><p class="muted">Os gabaritos das atividades originais foram preservados. A atribuição de oportunidades aos eixos e os itens novos são propostas digitais. Revise a matriz antes de autorizar seu uso nesta avaliação; esta revisão não constitui validação científica.</p><button data-action="matrix">${page===4?'Consultar matriz completa':''}</button><label class="check"><input type="checkbox" data-field="matrixReviewed" ${a.matrixReviewed?'checked':''}>O profissional revisou os critérios e correspondências propostos para esta aplicação.</label>${!a.matrixReviewed?'<p class="error muted">Resultados práticos e médias integradas indisponíveis até a revisão da matriz.</p>':''}</div><div class="grid"><div class="card"><h3>Radar RFT · verbal e prático</h3><div class="legend">${['Verbal','Prático','Média descritiva'].map((name,i)=>`<label><input type="checkbox" data-series="${i}" ${visible[i]?'checked':''}><span class="dot" style="background:${['#2f6ccc','#2a8650','#a67d15'][i]}"></span>${name}</label>`).join('')}</div>${radar(rows)}<p class="muted">Selecione um eixo para consultar as evidências. Ausências aparecem como lacunas.</p><button data-action="png">Exportar radar PNG</button></div><div class="card"><h3>Resultados e cobertura</h3>${resultTable(rows)}<details><summary>Resumo secundário: mediana das médias disponíveis</summary><p class="metric">${summary.value===null?'—':summary.value+'%'}</p><p class="muted">${summary.count} de 10 eixos contribuíram. Sem classificação global de aptidão; resultados com coberturas diferentes não devem ser usados como ranking.</p></details></div></div>${selectedAxis!==null?axisDetails(selectedAxis):''}<div class="card"><h3>Construção do perfil</h3><p class="muted">Conclusões e possibilidades devem ser produzidas ou revisadas pelo profissional. O radar Discovery resume somente os qualificadores; as respostas não são pontuadas automaticamente.</p>${reportFields()}${select('Situação do relatório','status',a.status,[['rascunho','Rascunho — revisão pendente'],['revisado','Revisado pelo profissional']])}<div class="actions"><button data-action="report-preview">Visualizar relatório</button><button class="primary" data-action="pdf">Salvar PDF / imprimir</button></div><p class="muted">O PDF é gerado pela impressão do navegador. Escolha “Salvar como PDF”. O relatório inclui lacunas de evidência e seu estado de revisão.</p></div>`;}
function legacyReportHTML(){const rows=results(a,content,matrix);return `<header class="report-heading"><h1>PERFIL PROFISSIONAL INDIVIDUALIZADO</h1><h2>LADO A | Employability</h2><p>${esc(a.protocol)} · ${esc(a.status==='revisado'?'Revisado pelo profissional':'RASCUNHO — revisão pendente')}</p></header><section><h3>1. Identificação</h3><p>Participante: ${esc(a.identity.code||'Não informado')} · Idade: ${esc(a.identity.age)}<br>Data: ${esc(a.identity.date)} · Profissional: ${esc(a.identity.professional||'Não informado')}<br>Comunicação preferida: ${esc(a.identity.communication||'Não informada')}</p><p>${esc(a.identity.notes)}</p></section><section><h3>2. Interesses e experiências</h3><div class="report-section">${esc(a.report.interests||'Não registrado')}\n${esc(a.report.experience||'')}</div></section><section><h3>3. Repertórios profissionais observados</h3><div class="report-section">${esc(a.report.observed||'Não registrado')}</div></section>${discoveryReport(a,content,games,matrix)}<section><h3>4. Resultados relacionais RFT e limites</h3><p>Percentual de oportunidades corretas e independentes na primeira tentativa. NO excluído do denominador. Mínimo operacional de duas oportunidades válidas, sem alegação de validade de medida.</p>${resultTable(rows)}<p>Matriz prática: ${a.matrixReviewed?'revisada pelo profissional nesta aplicação':'ainda não revisada; resultados práticos indisponíveis'}. Sem inferência de aptidão, diagnóstico ou aquisição de responder relacional derivado.</p></section><section><h3>5. Radar RFT · verbal e prático</h3>${radar(rows,true)}</section><section><h3>6. Preferências e condições facilitadoras</h3><div class="report-section">${esc(a.report.preferences||'Não registrado')}\n${esc(a.report.facilitators||'Não registrado')}</div></section><section><h3>7. Repertórios a desenvolver</h3><div class="report-section">${esc(a.report.develop||'Não registrado')}</div></section><section><h3>8. Possibilidades profissionais</h3><div class="report-section">${esc(a.report.possibilities||'Não registrado')}</div></section><section><h3>9. Considerações e revisão compartilhada</h3><div class="report-section">${esc(a.report.considerations||'Não registrado')}\n${esc(a.report.participantReview||'Revisão com o participante não registrada')}</div></section><section><h3>Condições e apoios registrados</h3>${content.probes.filter(p=>a.verbal[p.id]).map(p=>{const r=a.verbal[p.id];return `<p>${p.id}: ${esc(r.status)} · ajuda: ${esc(r.help||'nenhuma registrada')} · acesso: ${esc(r.access||'não registrado')} · ${esc(r.notes||'')}</p>`;}).join('')}${matrix.filter(m=>a.practical[m.id]?.review).map(m=>{const r=a.practical[m.id].review;return `<p>${esc(m.id)}: ${esc(r.status)} · ajuda: ${esc(r.help||'nenhuma registrada')} · acesso: ${esc(r.access||'não registrado')} · ${esc(r.notes||'')}</p>`;}).join('')}</section><footer><p>Protocolo piloto interno. Fontes: Manual de Aplicação e Caderno de Materiais v1.0. Itens novos e correspondências práticas são propostas digitais. Resultados situados nesta aplicação, sem finalidade normativa de seleção.</p></footer>`;}
function setNested(obj,path,value){const parts=path.split('.');let current=obj;for(let i=0;i<parts.length-1;i++){const key=parts[i];if(['__proto__','constructor','prototype'].includes(key))throw Error('Campo inválido');current[key] ||= {};current=current[key];}current[parts.at(-1)]=value;}
function setField(path,value){if(path.startsWith('verbal.')){const match=path.match(/^verbal\.(R\d+\.\d)\.(.+)$/);if(!match)return;const r=a.verbal[match[1]] ||= reviewDefault();r[match[2]]=value;}else if(path.startsWith('practical.')){const [,id,...rest]=path.split('.');const record=a.practical[id] ||= {};if(rest[0]==='review'){record.review ||= reviewDefault();record.review[rest[1]]=value;}else setNested(record,rest.join('.'),value);}else if(path.startsWith('interview.')){const [,id,key]=path.split('.');a.interview[id] ||= {answer:'',notes:'',qualifier:null,evidenceIds:[]};a.interview[id][key]=value;}else setNested(a,path,value);}
function invalidateReview(){if(a.status==='revisado')a.status='rascunho';}
root.addEventListener('input',e=>{const el=e.target;if(el.dataset.field){let value=el.type==='checkbox'?el.checked:el.value;if(/\.(correct|independent)$/.test(el.dataset.field))value=el.value==='true';setField(el.dataset.field,value);if(el.dataset.field!=='status')invalidateReview();save();}if(el.dataset.draft){const s=currentStage(),r=stageRecord(s);if(r.first)return;const value=el.type==='checkbox'?el.checked:el.value;setNested(r.draft,el.dataset.draft,value);r.actions.push({at:new Date().toISOString(),field:el.dataset.draft,value});invalidateReview();save();}});
root.addEventListener('change',e=>{const el=e.target;if(el.id==='assessment-select'){a=assessments.find(x=>x.id===el.value);selectedAxis=null;selectedDiscoveryBlock=null;interviewIndex=a.discovery.lastQuestion;discoveryPre=!a.discovery.preRegistrationComplete;render();}if(el.id==='discovery-jump'){interviewIndex=Number(el.value);a.discovery.lastQuestion=interviewIndex;save();render();}if(el.id==='probe-jump'){probeIndex=Number(el.value);render();}if(el.dataset.series){visible[Number(el.dataset.series)]=el.checked;render();}if(el.dataset.field==='matrixReviewed')render();if(el.dataset.field?.endsWith('.status')){const path=el.dataset.field;let r;if(path.startsWith('verbal.'))r=a.verbal[path.match(/^verbal\.(R\d+\.\d)/)[1]];else r=a.practical[path.split('.')[1]]?.review;if(r?.status==='observado'){if(path.startsWith('verbal.')){if(!r.answer.trim()){r.status='pendente';notify('Registre a primeira resposta antes de concluir a revisão.');}else r.first ||= {answer:r.answer,help:r.help,access:r.access,at:new Date().toISOString()};}else{const op=matrix.find(m=>m.id===path.split('.')[1]);if(op&&!a.practical[op.stage]?.first){r.status='pendente';notify('Registre a primeira entrega antes de concluir a revisão.');}}save();render();}}if(el.dataset.evidenceQuestion){const id=el.dataset.evidenceQuestion;const record=a.interview[id] ||= {answer:'',notes:'',qualifier:null,evidenceIds:[]};const ids=new Set(record.evidenceIds);if(el.checked)ids.add(el.value);else ids.delete(el.value);record.evidenceIds=[...ids];invalidateReview();save();}if(el.id==='import-file')importFile(el.files[0]);});
root.addEventListener('dragstart',e=>{if(e.target.dataset.object)e.dataTransfer.setData('text/plain',e.target.dataset.object);});root.addEventListener('dragover',e=>{if(e.target.closest('[data-drop]'))e.preventDefault();});root.addEventListener('drop',e=>{const drop=e.target.closest('[data-drop]');if(!drop)return;e.preventDefault();const s=currentStage(),r=stageRecord(s),id=e.dataTransfer.getData('text/plain');if(r.first||!s.items?.some(x=>x.id===id))return;r.draft[id]=drop.dataset.drop;r.actions.push({at:new Date().toISOString(),field:id,value:drop.dataset.drop,method:'drag'});invalidateReview();save();render();});
root.addEventListener('keydown',e=>{const trigger=e.target.closest('[data-action]');if((e.key==='Enter'||e.key===' ')&&e.target instanceof SVGElement&&trigger){e.preventDefault();trigger.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
root.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action.startsWith('dr-'))return;
if(action==='download-pdf'){await downloadAssessmentPDF();return;}
if(action==='office-review'){officeOpen=false;officeReviewOpen=true;render();return;}
if(action==='office-review-exit'){officeReviewOpen=false;page=3;render();return;}
if(action==='office-start'){officeReviewOpen=false;a.office ||= createOffice(a.id);officeOpen=true;if(a.office.status==='paused')applyOffice(a.office,'resume');save();render();return;}
if(action==='office-demo'){officeReviewOpen=false;a=createAssessment();a.identity.code='OFFICE-DEMO · fictício';a.identity.notes='Demonstração fictícia do Escritório Digital.';assessments.unshift(a);a.office=createOffice(a.id,{demo:true});officeOpen=true;save();render();return;}
if(action==='page'){page=Number(el.dataset.value);selectedAxis=null;selectedDiscoveryBlock=null;if(page===1){discoveryPre=!a.discovery.preRegistrationComplete;interviewIndex=a.discovery.lastQuestion;}}else if(action==='start-interview'){page=1;discoveryPre=true;}else if(action==='discovery-pre'){discoveryPre=true;}else if(action==='discovery-continue'){if(!a.discovery.preRegistrationComplete)interviewIndex=0;else interviewIndex=a.discovery.lastQuestion;a.discovery.preRegistrationComplete=true;discoveryPre=false;save();}else if(action==='discovery-clear'){setField(`interview.${content.interview[interviewIndex].id}.qualifier`,null);invalidateReview();save();}else if(action==='discovery-question'){page=1;discoveryPre=false;interviewIndex=Number(el.dataset.value);a.discovery.lastQuestion=interviewIndex;save();}else if(action==='discovery-block'){page=4;selectedDiscoveryBlock=Number(el.dataset.value);}else if(action==='discovery-evidence'){showDialog(practicalEvidence(el.dataset.value,a,games,matrix));return;}else if(action==='discovery-png'){await exportPNG('discovery');return;}else if(action==='mode'){participant=!participant;page=3;}else if(action==='pause'){save();notify('Pausa registrada. Seu progresso está preservado.');const r=stageRecord(currentStage());r.actions.push({at:new Date().toISOString(),event:'pausa'});save();return;}
else if(action==='new'){a=createAssessment();assessments.unshift(a);page=0;discoveryPre=true;selectedDiscoveryBlock=null;selectedAxis=null;interviewIndex=probeIndex=gameIndex=stageIndex=0;save();}
else if(action==='demo'){createDemo();page=4;profileTab='summary';selectedDiscoveryBlock=null;selectedAxis=null;save();}
else if(action==='export'){download(JSON.stringify(a,null,2),'application/json',`lado-a-${safeName(a.identity.code)}.json`);return;}
else if(action==='import'){document.querySelector('#import-file').click();return;}
else if(action==='discovery-prev'){interviewIndex=Math.max(0,interviewIndex-1);a.discovery.lastQuestion=interviewIndex;save();}else if(action==='discovery-next'){if(interviewIndex===35)page=2;else interviewIndex++;a.discovery.lastQuestion=interviewIndex;save();}
else if(action==='probe-prev'){probeIndex=Math.max(0,probeIndex-1);}else if(action==='probe-next'){if(probeIndex===29)page=3;else probeIndex++;}
else if(action==='game'){gameIndex=Number(el.dataset.value);stageIndex=0;}else if(action==='stage-prev'){stageIndex=Math.max(0,stageIndex-1);}else if(action==='stage-next'){if(stageIndex<games[gameIndex].stages.length-1)stageIndex++;else if(gameIndex<games.length-1){gameIndex++;stageIndex=0;}else if(participant){notify('As atividades foram registradas. Avise o profissional responsável.');return;}else page=4;}
else if(action==='move'){const s=currentStage(),r=stageRecord(s);if(r.first)return;const items=r.draft[el.dataset.group],i=Number(el.dataset.value),j=i+Number(el.dataset.direction);[items[i],items[j]]=[items[j],items[i]];r.actions.push({at:new Date().toISOString(),group:el.dataset.group,order:[...items]});invalidateReview();save();}
else if(action==='position'){const s=currentStage(),r=stageRecord(s);if(r.first)return;r.draft[el.dataset.row]=el.dataset.value;r.actions.push({at:new Date().toISOString(),field:el.dataset.row,value:el.dataset.value});invalidateReview();save();}
else if(action==='clarify'){const r=stageRecord(currentStage());if(!r.draft.question?.trim()){notify('Registre a pergunta ou hipótese antes de enviar.');return;}r.draft.clarified=true;r.actions.push({at:new Date().toISOString(),event:'esclarecimento',question:r.draft.question});invalidateReview();save();}
else if(action==='submit-stage'){const s=currentStage(),r=stageRecord(s);if(r.first)return;if(!hasResponse(s,r.draft)&&!r.actions.length){notify('Execute uma ação ou registre uma resposta. O avaliador pode marcar oportunidades não observadas como NO.');return;}r.first={at:new Date().toISOString(),draft:structuredClone(r.draft),actions:structuredClone(r.actions),conditions:structuredClone(r.conditions)};for(const op of matrix.filter(m=>m.stage===s.id)){const item=a.practical[op.id] ||= {};const suggestion=autoSuggestion(op,s,r.draft);item.review={...reviewDefault(),correct:suggestion===true,independent:!r.conditions.help.trim(),help:r.conditions.help,access:r.conditions.access,notes:r.conditions.notes,answer:JSON.stringify(r.draft)};}invalidateReview();save();}
else if(action==='axis'){selectedAxis=Number(el.dataset.value);page=4;}else if(action==='matrix'){showMatrix();return;}else if(action==='png'){await exportPNG();return;}else if(action==='pdf'){document.querySelector('#print-report').innerHTML=reportHTML();window.print();return;}else if(action==='report-preview'){showReport();return;}render();if(action==='axis')document.querySelector('.legend')?.scrollIntoView({block:'start'});if(action==='discovery-block')document.querySelector('#discovery-details')?.scrollIntoView({block:'start'});});
function hasResponse(s,d){if(s.type==='order')return true;return Object.values(d).some(v=>typeof v==='object'?Object.values(v).some(x=>x!==''&&x!==false):typeof v==='boolean'?v:!!String(v).trim());}
function safeName(v){return String(v||'avaliacao').replace(/[^a-zA-Z0-9_-]/g,'-').slice(0,60);}
let generatingPDF=false;
async function downloadAssessmentPDF(){if(externalMode&&(!accompaniedCompletion(a,qs,material.docs).ready||a.external?.phase!=='done'||!a.assisted?.completedAt)){notify('Conclua a revisão do avaliador antes de gerar o PDF final.');return;}if(generatingPDF)return;generatingPDF=true;const status=root.querySelector('#external-pdf-status');if(status)status.textContent='Gerando seu PDF…';try{const bytes=await createAssessmentPDF(a,content,material.docs);download(bytes,'application/pdf',`lado-a-${safeName(a.identity.code)}.pdf`);if(status)status.textContent='PDF gerado. Confira o arquivo baixado antes de enviá-lo.';}catch(err){if(status)status.textContent='Não foi possível gerar o PDF. Use o botão para tentar novamente.';notify(err.message||'Falha ao gerar PDF.');}finally{generatingPDF=false;}}
function download(data,type,name){const url=URL.createObjectURL(new Blob([data],{type}));const aEl=document.createElement('a');aEl.href=url;aEl.download=name;aEl.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function importFile(file){if(!file)return;try{if(file.size>15*1024*1024)throw Error('Arquivo acima do limite de 15 MB.');const imported=validatePractical(validateImport(file.name.toLowerCase().endsWith('.pdf')?await readAssessmentPDF(await file.arrayBuffer()):JSON.parse(await file.text()),material.docs),games,matrix);const knownStages=new Set(games.flatMap(g=>g.stages).map(s=>s.id));const knownOps=new Set(matrix.map(m=>m.id));if(Object.keys(imported.practical).some(id=>!knownStages.has(id)&&!knownOps.has(id)))throw Error('Oportunidade prática desconhecida.');const sourceId=imported.id;imported.id=crypto.randomUUID();if(imported.office){imported.office.sourceAssessmentId ||= sourceId;imported.office.assessmentId=imported.id;if(imported.office.status==='active')applyOffice(imported.office,'pause',{reason:'import'});}imported.identity.code+=' · importado';assessments.unshift(imported);a=imported;interviewIndex=a.discovery.lastQuestion;discoveryPre=!a.discovery.preRegistrationComplete;selectedDiscoveryBlock=null;selectedAxis=null;save();render();notify('Avaliação importada como uma cópia.');}catch(err){notify(err.message||'Não foi possível importar o arquivo.');}}
function showDialog(html){const dialog=document.createElement('dialog');dialog.style.cssText='width:min(1000px,94vw);max-height:90vh;border:1px solid #cbd8c9;border-radius:15px;padding:25px;color:#243c34';dialog.innerHTML=`<div class="actions" style="justify-content:flex-end"><button class="close-dialog">Fechar</button></div>${html}`;dialog.querySelector('.close-dialog').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();document.body.append(dialog);dialog.showModal();}
function showMatrix(){showDialog(`<h2>Matriz Verbal–Prática</h2><p>Proposta digital 0.1. Cada oportunidade tem um eixo principal. Não soma conclusão geral de jogos. Os critérios abaixo devem ser revisados pelo profissional.</p><div class="tablewrap"><table><thead><tr><th>Código / origem</th><th>Etapa / eixo</th><th>Instrução e relação</th><th>Resposta-alvo / critério</th><th>Sondagens relacionadas</th></tr></thead><tbody>${matrix.map(m=>{const game=games.find(g=>g.id===m.game),s=game.stages.find(s=>s.id===m.stage);return `<tr><td>${esc(m.id)}<br>${m.source==='novo'?'Novo':'Adaptado'}</td><td>${esc(game.name)} · ${esc(s.title)}<br>${m.axis===null?'Qualitativo':esc(content.axes[m.axis])}</td><td>${esc(s.instruction)}<br><br>${esc(m.target)}</td><td>${esc(m.expected)}</td><td>${m.axis===null?'—':m.verbal.join(', ')}</td></tr>`;}).join('')}</tbody></table></div>`);}
function showReport(){showDialog(reportHTML());}
async function exportPNG(){const svg=integratedRadar(integratedResults(a,qs));const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const img=new Image();img.src=url;await img.decode();const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1200;canvas.getContext('2d').drawImage(img,0,0,1600,1200);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error();download(blob,'image/png',`radar-discovery-${safeName(a.identity.code)}.png`);}catch{notify('Não foi possível exportar o radar.');}finally{URL.revokeObjectURL(url);}}

function demoDraft(s){const d=initDraft(s);if(s.type==='classify')for(const item of s.items)d[item.id]=s.override?.[item.id]||item[s.field];if(s.type==='order')for(const g of s.groups)d[g.name]=[...g.expected];if(s.type==='mark')for(const item of s.items)d[item.id]=s.expected.includes(item.id);if(s.type==='stock')for(const item of s.order){const expected=s.expected[item.id];d[item.id]={product:item.id,quantity:expected.quantity,decision:expected.decision,reason:expected.reason||'Sem impedimento'};}if(s.rows)for(const row of s.rows)d[row.id]=row.expected;if(s.type==='chat'){d.answer=s.id==='C2'?'A conferência terminou. Você pode seguir com a próxima etapa.':s.id==='C3'?'Vou colocar os urgentes primeiro. Quais documentos precisam sair agora?':'Quais relatórios, qual ordem e para quem devo entregar?';if(s.clarification){d.question='Quais relatórios, qual ordem e destinatário?';d.clarified=true;}}if(s.type==='interview')s.questions.forEach((q,i)=>d['Q'+i]=['Organizo arquivos e confiro listas.','Gosto de organizar informações.','Peço esclarecimento ou instrução escrita.','Checklist e um local com pouco ruído.','Como são as tarefas e os intervalos?'][i]);if(s.type==='checklist')s.items.forEach(item=>d[item.id]=true);d.message='Registro fictício: conferi todos os itens e comuniquei as pendências.';return d;}
function createDemo(){a=createAssessment();a.identity={code:'DEMO-001 · fictício',age:'23',date:'2026-10-13',professional:'Profissional demonstrativo',communication:'Escrita e fala, conforme preferência',notes:'Dados inteiramente fictícios. Não representam uma pessoa real.',agreement:true};content.interview.forEach((q,i)=>a.interview[q.id]={answer:demoAnswers[i],notes:'Resposta ilustrativa; não é modelo de resposta esperada.',qualifier:['D14','D16'].includes(q.id)?'none':(i%3===0?'partial':'complete'),evidenceIds:[]});a.discovery={preRegistrationComplete:true,lastQuestion:0};a.interview.D12.qualifier='complete';a.interview.D17.qualifier='complete';a.interview.D14.answer='Ainda não consigo identificar sozinho o erro e explicar como corrigi. Preciso de orientação para conferir.';a.interview.D16.answer='Ainda não costumo revisar meu trabalho sozinho; preciso que alguém indique o que conferir.';a.report={interests:'Interesse fictício por organização de arquivos e conferência de materiais.',experience:'Experiências fictícias com organização de listas e materiais domésticos.',preferences:'Prefere rotina previsível, instruções escritas e intervalos combinados.',observed:'Evidências fictícias de relatos Discovery; consultar respostas e critérios por habilidade. As simulações revisadas aguardam definição. Os minijogos são um complemento opcional.',facilitators:'Checklist, comunicação escrita, uso de teclado e ambiente com menor ruído.',develop:'Explorar desempenho em novas situações com mudança de instrução, preservando os apoios escolhidos.',possibilities:'Explorar tarefas de apoio administrativo e conferência de materiais, considerando as tarefas reais e as preferências.',considerations:'Demonstração funcional inteiramente fictícia. Os percentuais não são medida de aptidão e não comprovam generalização.',participantReview:'Exemplo fictício de devolutiva: participante mantém seu interesse em explorar organização de arquivos.'};qs.forEach((q,i)=>{const original=q.id.startsWith('D')?a.interview[q.id]:a.verbal[q.id];a.integrated.records[q.id]={...blankRecord(),answer:original?.answer||'Resposta fictícia.',score:q.domain===null?null:q.id.startsWith('R')?(original.correct?2:0):(['D14','D16'].includes(q.id)?0:2),help:original?.help||'',access:original?.access||'',independence:typeof original?.independent==='boolean'?(original.independent?'independent':'assisted'):'unknown',notes:'Demonstração fictícia; classificação ilustrativa.'};});a.interview={};assessments.unshift(a);notify('Demonstração fictícia criada; relatório permanece em rascunho.');}
bindOfficeReview(root,{getAssessment:()=>a,getDocs:()=>material.docs,isOpen:()=>officeReviewOpen||externalMode&&a.external?.phase==='review',save,render,notify});
bindExternalTest(root,{getAssessment:()=>a,getQuestions:()=>qs,getDocs:()=>material.docs,isActive:()=>externalMode,save,render,onPDF:downloadAssessmentPDF,notify});
bindOffice(root,{getAssessment:()=>a,isOpen:()=>officeOpen||externalMode&&a.external?.phase==='office',onPDF:downloadAssessmentPDF,onComplete:()=>{if(externalMode){a.external.phase='review';prepareOfficeReview(a,material.docs);save();render();}},save,render,exit:()=>{officeOpen=false;page=3;if(externalMode)a.external.phase='office-ready';render();},download,notify});
for(const assessment of assessments)if(assessment.office?.status==='active')applyOffice(assessment.office,'pause',{reason:'reload'});
if(assessments.some(item=>item.office))save();
if(!storageAvailable)notify('Não foi possível recuperar o armazenamento local. Nenhum dado existente foi sobrescrito. Exporte JSON antes de continuar.');
render();

function integratedInterview(){return interviewView(a,qs,content,discoveryPre,reportFields,matrix);}
function pendingGames(){return `<h2>Simulações profissionais</h2><div class="card"><span class="badge">Minijogo 1 · Adaptação digital</span><h3>LADO A Office | Central Administrativa</h3><p>Organização de documentos em cinco etapas. Respostas, revisões, pausas e pedidos de ajuda são registrados. As notas sugeridas exigem revisão e confirmação do avaliador.</p><div class="actions"><button class="primary" data-action="office-start">${!a.office?'Iniciar Escritório Digital':a.office.status==='completed'?'Consultar atividade concluída':'Retomar Escritório Digital'}</button><button data-action="office-demo">Testar com avaliação fictícia</button></div>${a.office?.status==='completed'?'<p>Para uma nova execução, crie outra avaliação.</p><button data-action="office-review">Revisar evidências do Office</button>':''}</div>`+`<div class="card"><span class="badge">Complemento opcional · execução em definição</span><h3>Minijogos em aberto</h3><p>Etapa opcional. Você já pode concluir o perfil com a entrevista Discovery. Os demais jogos interativos acrescentarão evidências de ações profissionais aos relatos, interesses e apoios. A execução será definida posteriormente.</p><ul>${games.slice(1).map(g=>`<li>${esc(g.name)}</li>`).join('')}</ul><p>A comparação futura usará os mesmos cinco eixos: Evidências relatadas, Desempenho nas simulações e Síntese conjunta — média descritiva. Os demais jogos ainda não calculam pontuações. O Office possui uma matriz própria, revisada pelo avaliador.</p><p>Os registros anteriores continuam preservados no JSON e no histórico.</p><button data-action="page" data-value="4">Concluir perfil pela entrevista</button><button data-action="dr-legacy">Consultar registros históricos</button></div>`;}
function profile(){return profileView(a,qs,reportFields,select,visible,profileTab,material.docs);}
function reportHTML(){return reportView(a,qs,material.docs);}
root.addEventListener('input',e=>{const el=e.target;if(!el.dataset.ir)return;const id=el.dataset.ir,key=el.dataset.key,r=a.integrated.records[id] ||= blankRecord();if(key==='score'){if(!r.answer.trim()){el.checked=false;notify('Registre a evidência antes de classificar.');return;}r.first ||= {answer:r.answer,help:r.help,access:r.access,at:new Date().toISOString()};r.score=Number(el.value);}else{r[key]=el.value;if(key==='answer'&&r.score!==null){r.score=null;root.querySelectorAll(`[name="score-${id}"]`).forEach(x=>x.checked=false);}}invalidateReview();save();});
root.addEventListener('change',e=>{const el=e.target;if(el.id==='dr-jump'){a.integrated.lastQuestion=Number(el.value);save();render();}if(el.dataset.irLink){const r=a.integrated.records[el.dataset.irLink] ||= blankRecord(),ids=new Set(r.evidenceIds);el.checked?ids.add(el.value):ids.delete(el.value);r.evidenceIds=[...ids];invalidateReview();save();}});
root.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el?.dataset.action.startsWith('dr-'))return;const action=el.dataset.action;if(action==='dr-tab'){profileTab=el.dataset.value;render();return;}if(action==='dr-continue'){a.discovery.preRegistrationComplete=true;discoveryPre=false;}if(action==='dr-prev')a.integrated.lastQuestion=Math.max(0,a.integrated.lastQuestion-1);if(action==='dr-next'){if(a.integrated.lastQuestion===qs.length-1)page=4;else a.integrated.lastQuestion++;}if(action==='dr-clear'){const r=a.integrated.records[qs[a.integrated.lastQuestion].id] ||= blankRecord();r.score=null;invalidateReview();}if(action==='dr-domain'){showDialog('<h2>Evidências da habilidade</h2>'+evidenceView(a,qs.filter(q=>q.domain===Number(el.dataset.value)),true));return;}if(action==='dr-reserve'){showDialog(reserveView(content));return;}if(action==='dr-legacy'){showDialog('<h2>Histórico da versão anterior</h2><p>Registros preservados; suas pontuações não alimentam o perfil reduzido.</p><pre class="records">'+esc(JSON.stringify({protocol:a.previousProtocol||a.protocol,interview:a.interview,verbal:a.verbal,practical:a.practical,sondagensIntegradas:Object.fromEntries(Object.entries(a.integrated.records).filter(([id])=>id.startsWith('R')))},null,2))+'</pre>');return;}if(action==='dr-png'){await exportPNG();return;}save();render();});
